+    private static void validatePassthroughHostsNotRouted(GatewayConfig gateway, List<ConfigError> errors) {
+        List<String> routedHosts = new ArrayList<>();
+        for (EndpointConfig endpoint : gateway.endpoints()) {
+            for (RouteConfig route : endpoint.routes()) {
+                Optional<String> host = routeHost(route);
+                if (host.isPresent()) {
+                    routedHosts.add(host.get());
+                }
+            }
+        }
+        for (String sniHost : passthroughSni(gateway).keySet()) {
+            if (isRoutedHost(sniHost, routedHosts)) {
+                errors.add(new ConfigError(GATEWAY_FILE, "/tls/passthrough_sni",
+                        "passthrough_sni host '%s' is also a routed host".formatted(sniHost)));
+            }
+            if (sniHost.isBlank()) {
+                errors.add(new ConfigError(GATEWAY_FILE, "/tls/passthrough_sni",
+                        "passthrough_sni host must not be blank"));
+            }
+            if (sniHost.contains("*")) {
+                errors.add(new ConfigError(GATEWAY_FILE, "/tls/passthrough_sni",
+                        "passthrough_sni host '%s' must not be a wildcard".formatted(sniHost)));
+            }
+        }
+    }
+
+    private static boolean isRoutedHost(String sniHost, List<String> routedHosts) {
+        boolean found = false;
+        for (String routed : routedHosts) {
+            if (routed.toLowerCase(Locale.ROOT).equalsIgnoreCase(sniHost.toLowerCase(Locale.ROOT))) {
+                found = true;
+                break;
+            }
+        }
+        if (found) {
+            return true;
+        } else {
+            return false;
+        }
+    }
